                          flexDirection: 'row',
                          alignItems: 'center',
                          justifyContent: 'space-between',
                          padding: 12,
                          borderRadius: 12,
                          backgroundColor: regSellsOtherDepartments ? '#ECFDF5' : '#F8FAFC',
                          borderWidth: 1,
                          borderColor: regSellsOtherDepartments ? '#10B981' : '#CBD5E1',
